-- Đang kết xuất đổ cấu trúc cơ sở dữ liệu cho news_db
DROP DATABASE IF EXISTS `news_db`;
CREATE DATABASE IF NOT EXISTS `news_db` /*!40100 DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci */;
USE `news_db`;

-- Đang kết xuất đổ cấu trúc cho bảng news_db.articles
DROP TABLE IF EXISTS `articles`;
CREATE TABLE IF NOT EXISTS `articles` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `content` longtext NOT NULL,
  `created_at` datetime(6) DEFAULT NULL,
  `slug` varchar(255) NOT NULL,
  `status` enum('CANCELLED','CHANGES_REQUESTED','DRAFT','IN_REVIEW','PUBLISHED') NOT NULL,
  `summary` varchar(500) DEFAULT NULL,
  `thumbnail_url` varchar(255) DEFAULT NULL,
  `title` varchar(255) NOT NULL,
  `updated_at` datetime(6) DEFAULT NULL,
  `views` int(11) NOT NULL,
  `author_id` bigint(20) NOT NULL,
  `category_id` bigint(20) NOT NULL,
  `published_at` datetime(6) DEFAULT NULL,
  `review_note` varchar(1000) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `UKsn7al9fwhgtf98rvn8nxhjt4f` (`slug`),
  KEY `FKe02fs2ut6qqoabfhj325wcjul` (`author_id`),
  KEY `FK7i4rryg7kqwyyrr08temnc71e` (`category_id`),
  CONSTRAINT `FK7i4rryg7kqwyyrr08temnc71e` FOREIGN KEY (`category_id`) REFERENCES `categories` (`id`),
  CONSTRAINT `FKe02fs2ut6qqoabfhj325wcjul` FOREIGN KEY (`author_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Đang kết xuất đổ dữ liệu cho bảng news_db.articles: ~9 rows (xấp xỉ)
INSERT INTO `articles` (`id`, `content`, `created_at`, `slug`, `status`, `summary`, `thumbnail_url`, `title`, `updated_at`, `views`, `author_id`, `category_id`, `published_at`, `review_note`) VALUES
	(1, '<p>&nbsp;</p><p><img src="https://cdn.nhandan.vn/images/88a27e1e0a137dcaaf86aa8e25f8f32598063dcadf452eefb31fc83292b4f235c232b13da9bdac753e7bcd86afe1260bad5ffbfd9ba1372cc75e9e8aa3204b02/ndo_br_1357028004190370406.jpg.avif" alt="Đội tuyển Việt Nam là đội tuyển tăng bậc mạnh nhất thế giới trong bảng xếp hạng mới nhất của FIFA. (Ảnh: THÀNH ĐẠT)" width="820" height="461"></p><p><i>Đội tuyển Việt Nam là đội tuyển tăng bậc mạnh nhất thế giới trong bảng xếp hạng mới nhất của FIFA. (Ảnh: THÀNH ĐẠT)</i></p><p>Theo đó, thầy trò huấn luyện viên Kim Sang Sik đạt 1.225,68 điểm, tăng 9 bậc và thêm 36,17 điểm so với lần cập nhật gần nhất. Đáng chú ý, <a target="_blank" rel="noopener noreferrer" href="https://nhandan.vn/tu-khoa/DoituyenVietNam-tag20480.html">đội tuyển Việt Nam</a> được FIFA ghi nhận là đội tuyển có bước tiến mạnh nhất trong đợt xếp hạng lần này.</p><p>Xếp sau Việt Nam về mức cải thiện thứ hạng là Bosnia, Nepal và Bhutan khi cùng tăng 6 bậc. Ở chiều ngược lại, Malaysia trở thành đội tuyển giảm sâu nhất khi tụt 17 bậc xuống vị trí 138 thế giới, đồng thời rơi xuống hạng 5 khu vực Đông Nam Á sau khi bị Philippines vượt qua.</p><p>Ở khu vực châu Á, nhóm 5 đội tuyển dẫn đầu tiếp tục gồm Nhật Bản (hạng 18 thế giới), Iran (21), Hàn Quốc (25), Australia (27) và Uzbekistan (50), qua đó khẳng định vị thế ổn định của các nền bóng đá hàng đầu châu lục.</p><p>&nbsp;</p><p>Trên bảng xếp hạng thế giới, ba vị trí dẫn đầu lần lượt thuộc về Pháp, Tây Ban Nha và Argentina.</p><p>Một điểm mới đáng chú ý trong kỳ FIFA Days tháng 3/2026 là FIFA lần đầu áp dụng cơ chế cập nhật bảng xếp hạng theo thời gian thực. Theo đó, điểm số và thứ hạng của các đội tuyển quốc gia, cả nam và nữ, có thể thay đổi ngay trong quá trình các trận đấu quốc tế diễn ra.</p><p>&nbsp;</p><p>Mỗi bàn thắng trong các trận đấu quốc tế đều có khả năng tác động trực tiếp tới điểm số và vị trí xếp hạng, mang lại góc nhìn trực quan hơn về sự biến động của bóng đá thế giới. Tuy nhiên, các thay đổi trong thời gian thi đấu chỉ mang tính tạm thời; bảng xếp hạng chính thức vẫn được xác nhận sau khi toàn bộ các trận đấu thuộc kỳ FIFA Days khép lại.</p><p>Dù công thức tính điểm không thay đổi, cơ chế cập nhật mới được kỳ vọng giúp người hâm mộ theo dõi sát sao hơn diễn biến thứ hạng của các đội tuyển, đồng thời gia tăng sức hấp dẫn cho các trận đấu quốc tế.</p><p>Việc trở lại Top 100 thế giới là dấu mốc tích cực đối với đội tuyển Việt Nam, phản ánh sự cải thiện về chuyên môn cũng như hiệu quả từ quá trình chuẩn bị, xây dựng lực lượng và thi đấu trong thời gian qua. Đây được xem là nền tảng quan trọng để đội tuyển tiếp tục hướng tới những mục tiêu cao hơn ở các đấu trường khu vực và châu lục trong thời gian tới.</p>', '2026-04-03 15:14:53.000000', 'doi-tuyen-viet-nam-chuan-bi-cho-giai-dau-lon', 'PUBLISHED', 'Các cầu thủ đang tập luyện hăng say chờ ngày ra trận...', 'https://res.cloudinary.com/du2ur4oya/image/upload/v1775378190/1775378188540_t%E1%BA%A3i_xu%E1%BB%91ng.jpg.jpg', 'Đội tuyển Việt Nam chuẩn bị cho giải đấu lớn', '2026-04-06 16:28:19.000000', 38, 1, 1, '2026-04-05 08:36:28.000000', NULL),
	(2, '<h2><strong>Laptop AI 2026: Vì sao chỉ NPU là chưa đủ?</strong></h2><p>Không thể phủ nhận rằng các NPU hiện đại, với sức mạnh lên đến 50 TOPS trên những dòng chip như Ryzen AI hay Intel Core Ultra đã làm rất tốt nhiệm vụ xử lý các tác vụ AI nền. Từ tối ưu pin, khử nhiễu âm thanh, cho đến các tính năng như <a target="_blank" rel="noopener noreferrer" href="https://cellphones.com.vn/sforum/windows-studio-effects">Windows Studio Effects</a> thậm chí là thay thế <a target="_blank" rel="noopener noreferrer" href="https://cellphones.com.vn/linh-kien/cpu.html">CPU</a> xử lý một số tác vụ, tất cả đều trở nên mượt mà và tiết kiệm năng lượng hơn nhờ NPU.</p><figure class="image"><img style="aspect-ratio:1200/675;" src="https://cdn-media.sforum.vn/storage/app/media/thongvo/xu-huong-laptop-gaming-ai-mong-nhe-2026/xu-huong-laptop-gaming-ai-mong-nhe-2026-3.jpg" alt="Laptop AI 2026: Vì sao chỉ NPU là chưa đủ?" width="1200" height="675"><figcaption>Laptop AI 2026: Vì sao chỉ NPU là chưa đủ?</figcaption></figure><p>Tuy nhiên, khi bước vào các tác vụ nặng như huấn luyện mô hình, xử lý AI tạo sinh (Generative AI), hay chơi <a target="_blank" rel="noopener noreferrer" href="https://cellphones.com.vn/sforum/s-games">game</a> và dựng hình 3D phức tạp, GPU mới thực sự là “nhân tố quyết định”. Các dòng GPU NVIDIA RTX 50 Series dựa trên kiến trúc <a target="_blank" rel="noopener noreferrer" href="https://cellphones.com.vn/sforum/gpu-blackwell-cua-nvidia-rtx-50-series-se-mang-toi-buoc-nhay-vot-hieu-nang-lon-nhat-trong-lich-su">Blackwell</a> mang đến bước nhảy vọt về hiệu năng AI, đặc biệt với <a target="_blank" rel="noopener noreferrer" href="https://cellphones.com.vn/sforum/tensor-core">nhân Tensor</a> thế hệ mới.</p><p>Nhờ đó, <a target="_blank" rel="noopener noreferrer" href="https://cellphones.com.vn/laptop.html">laptop</a> trang bị RTX 50 Series có thể:</p><ul><li>Tăng tốc xử lý các mô hình ngôn ngữ lớn với tốc độ cực nhanh, đáp ứng nhu cầu xử lý dữ liệu, tạo ảnh AI nhanh chóng mà không cần internet.</li><li>Gia tăng khung hình lên đến nhiều lần với <a target="_blank" rel="noopener noreferrer" href="https://cellphones.com.vn/sforum/dlss-la-gi-nguyen-ly-hoat-dong-va-loi-ich">DLSS</a>/FSR và Multi Frame Generation mang đến trải nghiệm mượt mà với chất lượng hình ảnh gần như không đổi.</li><li>Giảm độ trễ đáng kể với NVIDIA Reflex/ AMD Anti-Lag tối đa lợi thế trong các tựa game competitive.</li></ul><p>Sự kết hợp giữa NPU và GPU không chỉ là bổ sung, mà là cộng hưởng, giúp laptop vừa tiết kiệm điện khi cần, vừa bùng nổ hiệu năng khi phải xử lý tác vụ nặng.</p><h2><strong>Top laptop gaming AI mỏng nhẹ đáng chú ý nhất 2026</strong></h2><h3><strong>TUF Gaming A14 (2026): Nhẹ như laptop văn phòng, nhưng không hề “yếu”</strong></h3><p>TUF Gaming A14 (2026) là minh chứng rõ ràng cho việc hiệu năng cao không còn đồng nghĩa với cồng kềnh. Với trọng lượng chỉ 1.48kg và độ mỏng 16.9mm, đây là một trong những laptop gaming AI 14-inch nhẹ nhất hiện nay.</p><figure class="image"><img style="aspect-ratio:1200/675;" src="https://cdn-media.sforum.vn/storage/app/media/thongvo/xu-huong-laptop-gaming-ai-mong-nhe-2026/xu-huong-laptop-gaming-ai-mong-nhe-2026-4.jpg" alt="ASUS TUF Gaming A14 (2026)" width="1200" height="675"></figure><p>Điểm đáng chú ý nằm ở cấu hình “AI lai” với vi xử lý AMD Ryzen AI Max+ 392, tích hợp NPU 50 TOPS. Máy hỗ trợ RAM lên đến 64GB LPDDR5X, đủ khả năng chạy các mô hình AI lớn (LLM) ngay trên thiết bị. Đặc biệt, iGPU Radeon 8060S mang lại hiệu năng tiệm cận GPU rời RTX 5060, nhưng tiêu thụ điện năng thấp hơn đáng kể, một lợi thế cực lớn cho người dùng di động.</p><h3><strong>ROG Zephyrus G14 (2026): Cân bằng hoàn hảo giữa thiết kế và sức mạnh</strong></h3><p>ROG Zephyrus G14 tiếp tục giữ vững vị thế trong phân khúc laptop gaming AI mỏng nhẹ cao cấp nhờ sự kết hợp giữa thiết kế tinh tế và hiệu năng mạnh mẽ. Bộ khung nhôm CNC nguyên khối không chỉ mang lại độ bền cao mà còn tạo cảm giác cao cấp rõ rệt.</p><figure class="image"><img style="aspect-ratio:1200/675;" src="https://cdn-media.sforum.vn/storage/app/media/thongvo/xu-huong-laptop-gaming-ai-mong-nhe-2026/xu-huong-laptop-gaming-ai-mong-nhe-2026-2.jpg" alt="ASUS ROG Zephyrus G14 (2026)" width="1200" height="675"></figure><p>Trang bị Intel Core Ultra 9 386H với NPU 50 TOPS, chiếc máy này không chỉ xử lý tốt các tác vụ AI mà còn đáp ứng nhu cầu sáng tạo nội dung chuyên sâu. <a target="_blank" rel="noopener noreferrer" href="https://cellphones.com.vn/man-hinh.html">Màn hình</a> Nebula HDR OLED độ phân giải 3K, tần số quét 120Hz và độ chính xác màu cực cao (Delta E &lt; 1) biến Zephyrus G14 thành một trạm làm việc di động lý tưởng cho designer, editor và content creator.</p><h3><strong>ROG Flow Z13-KJP: Cỗ máy AI di động mang hơi thở tương lai</strong></h3><p>ROG Flow Z13-KJP là một sản phẩm mang tính biểu tượng khi kết hợp giữa <a target="_blank" rel="noopener noreferrer" href="https://cellphones.com.vn/sforum">công nghệ</a> và cảm hứng thiết kế từ <a target="_blank" rel="noopener noreferrer" href="https://cellphones.com.vn/sforum/ces-2026-asus-rog-flow-z13-kjp">KOJIMA PRODUCTIONS</a>. Với ngoại hình đậm chất viễn tưởng lấy cảm hứng từ bộ giáp Ludens, đây không chỉ là một thiết bị công nghệ đỉnh cao mà còn là một tuyệt tác dành cho game thủ yêu thích các sản phẩm game của <a target="_blank" rel="noopener noreferrer" href="https://cellphones.com.vn/sforum/hideo-kojima-mot-trong-nhung-tua-game-tiep-theo-cua-toi-se-tro-thanh-chuan-muc-moi">Hideo Kojima</a>.</p><figure class="image"><img style="aspect-ratio:1200/675;" src="https://cdn-media.sforum.vn/storage/app/media/thongvo/xu-huong-laptop-gaming-ai-mong-nhe-2026/xu-huong-laptop-gaming-ai-mong-nhe-2026-1.jpg" alt="ASUS ROG Flow Z13-KJP" width="1200" height="675"></figure><p>Sức mạnh của máy đến từ vi xử lý AMD Ryzen AI Max+ 395 cùng bộ nhớ RAM hợp nhất lên đến 128GB. Với hiệu suất Nhờ đó, thiết bị có thể chạy mượt các mô hình ngôn ngữ lớn ngay trên máy mà không cần đến internet. Ngoài ra, khả năng mở rộng qua USB4 cho phép kết nối GPU rời XG Mobile (tối đa RTX 5090), biến chiếc gaming <a target="_blank" rel="noopener noreferrer" href="https://cellphones.com.vn/tablet.html">tablet</a> này thành một “quái vật hiệu năng” thực thụ khi cần.</p><h2><strong>Lợi ích thực tế của laptop Hybrid AI (NPU + RTX 50)</strong></h2><p>Điểm khác biệt lớn nhất của các <a target="_blank" rel="noopener noreferrer" href="https://cellphones.com.vn/laptop/gaming.html">laptop gaming AI</a> thế hệ mới nằm ở khả năng xử lý AI cục bộ (Local AI). Người dùng có thể chạy các mô hình ngôn ngữ lớn như <a target="_blank" rel="noopener noreferrer" href="https://cellphones.com.vn/sforum/deepseek-v3-vs-r1">DeepSeek R1</a>, Chat-GPT-OSS-20B trực tiếp trên máy thông qua các công cụ như LM Studio, đảm bảo tính bảo mật dữ liệu và không phụ thuộc vào kết nối internet.</p><p>Bên cạnh đó, các công nghệ như Two-Way AI Noise Cancelation giúp loại bỏ đến 95% tiếng ồn môi trường mà không ảnh hưởng đến hiệu năng tổng thể. Điều này đặc biệt hữu ích cho game thủ, streamer hay những người thường xuyên họp online.</p><p>Không thể không nhắc đến trải nghiệm sử dụng yên tĩnh hơn nhờ các công nghệ tản nhiệt thông minh như 0dB Ambient Cooling. Khi xử lý tác vụ nhẹ, quạt có thể dừng hoàn toàn, mang lại không gian làm việc gần như tuyệt đối yên tĩnh, một điểm cộng lớn cho môi trường văn phòng hoặc làm việc sáng tạo.</p><h2><strong>Kết luận: Đâu là chiếc laptop AI phù hợp với bạn?</strong></h2><p>Sự phát triển của “Hybrid AI” đã đưa laptop gaming AI mỏng nhẹ lên một tầm cao mới, nơi hiệu năng và tính di động không còn là hai yếu tố đối lập.</p><p>Nếu bạn cần một thiết bị gọn nhẹ để mang theo mỗi ngày nhưng vẫn đủ sức xử lý công việc AI, TUF Gaming A14 hoặc ROG Zephyrus G14 là những lựa chọn cực kỳ hợp lý. Ngược lại, nếu bạn là người đam mê khám phá công nghệ, sáng tạo nội dung chuyên sâu và cần sức mạnh AI tối đa, ROG Flow Z13-KJP sẽ là cỗ máy đáng để đầu tư.</p><p>Ở thời điểm 2026, sở hữu một chiếc laptop AI mỏng nhẹ không còn đơn thuần là chạy theo xu hướng. Đó là cách bạn trang bị cho mình một “cộng sự” thông minh, linh hoạt và luôn sẵn sàng đồng hành trong mọi thử thách, từ công việc, sáng tạo cho đến giải trí.</p>', '2026-04-03 15:14:53.000000', 'hybrid-ai-la-gi-xu-huong-moi-dinh-hinh-laptop-mong-nhe-nam-2026', 'PUBLISHED', 'Năm 2026 đánh dấu một bước ngoặt lớn trong cách chúng ta định nghĩa về laptop AI mỏng nhẹ.\r\n\r\nNếu như trước đây, NPU (Neural Processing Unit) được xem là trung tâm của các tác vụ trí tuệ nhân tạo, thì giờ đây, một chiếc laptop AI “chuẩn chỉnh” phải là sự kết hợp giữa NPU tiết kiệm điện và GPU RTX 50 Series mạnh mẽ. Mô hình “Hybrid AI” này mang lại hiệu năng vượt trội trong một thiết kế siêu di động, mở ra trải nghiệm hoàn toàn mới cho cả công việc lẫn giải trí.', 'https://res.cloudinary.com/du2ur4oya/image/upload/v1775378255/1775378251651_xu-huong-laptop-gaming-ai-mong-nhe-2026-cover.jpg.jpg', 'Hybrid AI là gì? Xu hướng mới định hình laptop mỏng nhẹ năm 2026', '2026-04-06 16:14:23.000000', 53, 1, 2, '2026-04-05 08:37:31.000000', NULL),
	(3, '<p>Từ 6h30, nhiều thí sinh có mặt tại điểm thi trường Đại học Công nghệ Kỹ thuật TP HCM, phường Thủ Đức.</p><p>Năm nay, hơn 137.000 thí sinh đăng ký dự thi đánh giá năng lực Đại học Quốc gia TP HCM, là kỷ lục với một kỳ thi riêng trong cả nước. Trong đó, chừng 133.500 em có mặt.</p><p>Điều này trong bối cảnh 8 trường thành viên Đại học Quốc gia TP HCM và nhiều trường khác chuyển sang xét tuyển kết hợp nhiều loại điểm. Kết quả thi đánh giá năng lực chiếm tỷ trọng lớn.</p><figure class="image"><img style="aspect-ratio:1200/800;" src="https://res.cloudinary.com/du2ur4oya/image/upload/v1775373251/1775373249227_233A3371-1775352261-1775352570.webp.webp" width="1200" height="800"></figure><figure class="image"><img style="aspect-ratio:1200/800;" src="https://i1-vnexpress.vnecdn.net/2026/04/05/233a3115-1775354684-1775355275.jpg?w=1200&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=UNpBjd3_DllN0kaibmbakQ" width="1200" height="800"></figure><p>Các tuyến đường quanh các điểm thi đông đúc thí sinh, phụ huynh. Lực lượng dân quân, sinh viên tình nguyện... thường xuyên túc trực điều tiết giao thông, hướng dẫn chỗ đỗ xe, chỉ đường.</p><p>Nhà cách trường 500 m nhưng ông Đào Minh Vinh, 52 tuổi vẫn chạy xe chở con gái Đào Nguyễn Như Quỳnh tới điểm thi.</p><p>"Tôi muốn đi cùng để tiếp thêm động lực cho con, luôn dặn cháu cứ cố gắng hết mình là được, không cần áp lực nhiều", ông nói.</p><figure class="image"><img style="aspect-ratio:1200/800;" src="https://i1-vnexpress.vnecdn.net/2026/04/05/233a4125-1775354959-1775355275.jpg?w=1200&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=SVbqud5m6fa4lCoeMU6D7A" width="1200" height="800"></figure><figure class="image"><img style="aspect-ratio:1200/800;" src="https://i1-vnexpress.vnecdn.net/2026/04/05/233a3650-1775354965-1775355275.jpg?w=1200&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=ueti9BOZGMemhqFUZUdxTw" width="1200" height="800"></figure><figure class="image"><img style="aspect-ratio:1200/1500;" src="https://i1-vnexpress.vnecdn.net/2026/04/05/233a3237-1775354837-1775355276.jpg?w=1200&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=tjPDwC_9b-a3m5kquCFgeA" width="1200" height="1500"></figure><p>Tay trái của Nguyễn Phạm Phương Thảo (THPT Hiệp Bình) phải bó bột sau khi bị trật khớp cách đây một tuần. Thảo thấy vẫn may mắn vì còn làm bài được.</p><p>Nữ sinh đặt mục tiêu đạt từ 800/1200 điểm trở lên, đặt nguyện vọng vào ngành Luật của trường Đại học Luật TP HCM, Kinh tế - Luật (Đại học Quốc gia TP HCM). Để chuẩn bị cho kỳ thi, Thảo đăng ký 2 khóa ôn luyện song song từ đầu năm học.</p><p>“Năm nay điểm đánh giá năng lực là một phần quan trọng để tuyển sinh đại học nên em cũng hơi căng thẳng, mong đạt điểm tốt ngay đợt đầu để dành thời gian ôn tập thi tốt nghiệp THPT”. Thảo nói.</p><p>&nbsp;</p>', '2026-04-05 07:14:51.000000', 'hon-133000-thi-sinh-bat-dau-cuoc-dua-vao-dai-hoc-lon-nhat-phia-nam', 'PUBLISHED', 'TP HCM - Hơn 133.000 thí sinh dự thi đánh giá năng lực Đại học Quốc gia TP HCM sáng 5/4, đông nhất từ trước đến nay, để lấy điểm xét kết hợp vào đại học.', 'https://res.cloudinary.com/du2ur4oya/image/upload/v1775373294/1775373291130_thi-1775354582-1775354596-1775355274.webp.webp', 'Hơn 133.000 thí sinh bắt đầu cuộc đua vào đại học lớn nhất phía Nam', '2026-04-06 03:12:24.000000', 4, 1, 7, '2026-04-05 07:14:51.000000', NULL),
	(4, '<p>Lực lượng Mỹ giải cứu được phi công còn lại trong vụ tiêm kích F-15 bị bắn hạ tại Iran, sau cuộc đấu súng ác liệt và sự cố vào phút chót.</p><p>"Chúng ta đã cứu được cậu ấy! Trong vài giờ qua, quân đội Mỹ đã thực hiện thành công một trong những chiến dịch tìm kiếm và cứu nạn táo bạo nhất lịch sử. Người được giải cứu là một sĩ quan phi hành đoàn tuyệt vời, một đại tá rất mực được kính trọng. Tôi vô cùng hạnh phúc được thông báo với các bạn rằng cậu ấy hiện bình an vô sự!", Tổng thống Trump viết trên mạng xã hội Truth Social.</p><p>Ông Trump cho biết quân đội Mỹ đã theo dõi vị trí của phi công 24/24 và "tích cực lên kế hoạch giải cứu". Quân đội Mỹ đã điều "hàng chục máy bay, được trang bị những vũ khí nguy hiểm nhất thế giới, cho chiến dịch này", Tổng thống mô tả. "Cậu ấy bị thương, nhưng sẽ ổn thôi".</p><p>Ông Trump nhấn mạnh toàn bộ lực lượng tham gia chiến dịch đều đã ra khỏi Iran an toàn. "Việc không một người Mỹ nào thiệt mạng hay bị thương một lần nữa chứng minh rằng chúng ta đã đạt được thế kiểm soát tuyệt đối trên không phận Iran", Tổng thống Mỹ viết.</p><figure class="image"><img style="aspect-ratio:680/383;" src="https://i1-vnexpress.vnecdn.net/2026/04/05/AP26093698370653-1-1775363344-2131-1775363658.jpg?w=680&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=VfSTmLHNcw7FnAyLpAB_Vg" alt="Một chiếc tiêm kích F-15 tại Mỹ hồi năm 2017. Ảnh: AP" width="680" height="383"></figure><p>Một chiếc tiêm kích F-15 tại Mỹ hồi năm 2017. Ảnh: <i>AP</i></p><p>&nbsp;</p><p>Hai thành viên tổ bay trên chiếc F-15E Strike Eagle đã phóng ghế thoát hiểm khi tiêm kích bị bắn hạ tại Iran ngày 3/4. Trong khi phi công buồng trước được giải cứu nhanh chóng, sĩ quan điều khiển vũ khí, hay còn gọi là phi công buồng sau, mắc kẹt tại Iran. Sự việc khiến Mỹ kích hoạt chiến dịch tìm kiếm khẩn cấp.</p><p>Theo <i>NY Times</i>, chiến dịch giải cứu diễn ra vào đêm 4/4, huy động hàng trăm lính đặc nhiệm, hàng chục máy bay chiến đấu, trực thăng cùng các năng lực tình báo mạng, không gian và nhiều phương tiện trinh sát khác. Các quan chức Mỹ mô tả đây là nhiệm vụ "đầy rủi ro" khi đặc nhiệm Mỹ phải tiến sâu vào lãnh thổ Iran, các vận tải cơ C-130 và trực thăng phải bay thấp với tốc độ chậm qua những vùng núi hiểm trở để xác định vị trí phi công.</p><p>Máy bay Mỹ liên tục dội bom và xả súng vào các đoàn xe Iran nhằm ngăn họ tiếp cận khu vực phi công ẩn náu. Một cuộc đấu súng nổ ra khi lực lượng Mỹ áp sát vị trí phi công, người mang theo súng ngắn, thiết bị phát tín hiệu định vị và hệ thống liên lạc bảo mật.</p><p>Một diễn biến bất ngờ xảy ra vào phút chót sau khi phi công được giải cứu: Hai chiếc máy bay vận tải làm nhiệm vụ đưa đội đặc nhiệm và phi công về nơi an toàn đã mắc kẹt tại một căn cứ hẻo lánh ở Iran. Các chỉ huy sau đó quyết định điều thêm ba máy bay khác đến để di tản toàn bộ quân nhân Mỹ. Họ "cho nổ tung hai chiếc máy bay gặp sự cố thay vì để chúng rơi vào tay phía Iran", theo <i>NY Times</i>.</p><p>Quân đội Iran cũng đã triển khai chiến dịch tìm kiếm phi công, kêu gọi người dân hỗ trợ và treo thưởng cho bất kỳ ai bắt được lính Mỹ.</p><p>Tiêm kích F-15 bị bắn hạ tại khu vực có làn sóng đối lập với chính quyền Iran. Do đó, phi công Mỹ có thể đã dựa vào hỗ trợ của người dân địa phương để ẩn náu. Trong những tình huống như vậy, CIA thường đóng vai trò kết nối với những thường dân sẵn lòng giúp đỡ binh sĩ.</p><p><strong>Phương Vũ</strong> (Theo <i>Reuters, NY Times, AFP</i>)</p>', '2026-04-05 07:17:02.000000', 'my-giai-cuu-thanh-cong-phi-cong-tren-tiem-kich-f-15-bi-ban-ha', 'PUBLISHED', 'Lực lượng Mỹ giải cứu được phi công còn lại trong vụ tiêm kích F-15 bị bắn hạ tại Iran, sau cuộc đấu súng ác liệt và sự cố vào phút chót.', 'https://res.cloudinary.com/du2ur4oya/image/upload/v1775373424/1775373422197_AP26093698370653-1-1775363344-2131-1775363658.webp.webp', 'Mỹ giải cứu thành công phi công trên tiêm kích F-15 bị bắn hạ', '2026-04-05 07:17:02.000000', 0, 1, 8, '2026-04-05 07:17:02.000000', NULL),
	(5, '<p>Việc chiến đấu Mỹ liên tiếp bị bắn rơi phủ bóng đen lên các tuyên bố chiến thắng của ông Trump, người vừa khẳng định năng lực quân sự Iran đã "kiệt quệ".</p><p>Ngày 1/4, Tổng thống Mỹ Donald Trump phát biểu trước toàn quốc rằng "chúng ta đã đánh bại Iran". Ông khẳng định Tehran "đã bị tàn phá về quân sự, kinh tế và mọi phương diện khác".</p><p>Ngày 2/4, người đứng đầu Bộ Tư lệnh Trung tâm Mỹ (CENTCOM) xác nhận thông điệp đó khi nói rằng "các hệ thống phòng không và tên lửa của Iran phần lớn đã bị phá hủy".</p><p>Thế nhưng, chỉ một ngày sau, không quân Mỹ trải qua "ngày thảm họa", khi liên tiếp mất hai máy bay và ít nhất hai trực thăng trúng đạn. Iran sáng 3/4 tuyên bố đã bắn hạ một tiêm kích Mỹ, buộc hai phi công nhảy dù trên lãnh thổ nước này.</p><p>Tiêm kích bị bắn rơi được xác định là mẫu F-15E Strike Eagle, một trong những loại chiến đấu cơ chủ lực của Mỹ trong chiến dịch Cơn thịnh nộ Kinh hoàng tấn công Iran. Một chiến dịch tìm kiếm quy mô lớn được phát động, giúp Mỹ tìm thấy và giải cứu phi công thứ nhất, nhưng người thứ hai vẫn mất tích bên trong lãnh thổ Iran.</p><p>Đây được cho là chiếc máy bay có người lái đầu tiên của Mỹ bị hỏa lực đối phương bắn hạ kể từ khi Chiến dịch Cơn thịnh nộ Kinh hoàng bắt đầu hôm 28/2.</p><p><picture><source srcset="https://i1-vnexpress.vnecdn.net/2026/04/04/AFP-20260201-ZDN100605M-v1-Hig-8799-5343-1775291830.jpg?w=680&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=uAOyNwLYIJtbOXI30_tIwg 1x, https://i1-vnexpress.vnecdn.net/2026/04/04/AFP-20260201-ZDN100605M-v1-Hig-8799-5343-1775291830.jpg?w=1020&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=8TNilnMslF61sY83f9IAYQ 1.5x, https://i1-vnexpress.vnecdn.net/2026/04/04/AFP-20260201-ZDN100605M-v1-Hig-8799-5343-1775291830.jpg?w=680&amp;h=0&amp;q=100&amp;dpr=2&amp;fit=crop&amp;s=u9Rq9mgnMcjKq8hK8xrdHw 2x"><img src="https://i1-vnexpress.vnecdn.net/2026/04/04/AFP-20260201-ZDN100605M-v1-Hig-8799-5343-1775291830.jpg?w=680&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=uAOyNwLYIJtbOXI30_tIwg" alt="Tiêm kích F-15E của Không quân Mỹ. Ảnh: AFP" width="680" height="453"></picture></p><p>Tiêm kích F-15E của Không quân Mỹ. Ảnh: <i>AFP</i></p><p>Trong khi chiến dịch tìm kiếm được Mỹ tiến hành, Iran thông báo lực lượng nước này tiếp tục bắn hạ một cường kích A-10. <i>NY Times</i> dẫn lời các quan chức Mỹ cho biết phi công chiếc A-10 đã cố điều khiển máy bay rời khỏi không phận Iran trước khi phóng ghế thoát hiểm và được giải cứu an toàn.</p><p>Hai quan chức Mỹ còn nói với <i>Reuters ­</i>rằng hai trực thăng thuộc đội tìm kiếm đã trúng hỏa lực Iran, song đã rời khỏi không phận nước này thành công. Một quan chức cho biết những người có mặt trên hai máy bay vẫn an toàn, nhưng ít nhất một quân nhân đã bị thương.</p><p>Các sự cố này không đồng nghĩa Iran đã đảo ngược vị thế quân sự với Mỹ, nhưng chúng đã "dội gáo nước lạnh" vào các tuyên bố chiến thắng mà ông Trump liên tục đưa ra gần đây. Nó cũng chứng minh rằng bất chấp chiến dịch tập kích dữ dội của Mỹ - Israel, Iran vẫn đủ sức gây tổn thất cho Washington và tạo ra thách thức ngày càng lớn với ông Trump, theo Dan De Luce, nhà phân tích của <i>NBC News</i>.</p><p>Cả Tổng thống Trump và Bộ trưởng Quốc phòng Pete Hegseth đều từng ám chỉ rằng không quân Mỹ và Israel đang "tự do hoạt động" trên bầu trời Iran, mô tả lưới phòng không của nước này không còn khả năng chống trả.</p><p>Khi được hỏi liệu Iran có còn khả năng đe dọa máy bay Mỹ hay không, ông Trump hôm 1/4 một lần nữa khẳng định "họ không có thiết bị phòng không. Radar của họ đã bị phá hủy 100%. Chúng ta là lực lượng quân sự không thể ngăn cản".</p><p>Tuy nhiên, Iran ngay sau đó phóng ít nhất 50 tên lửa đạn đạo và hơn 150 máy bay không người lái (UAV) nhắm vào mục tiêu Mỹ và đồng minh ở vùng Vịnh.</p><p>Theo một quan chức Mỹ và các nguồn tin am hiểu tình hình, khoảng 50% số bệ phóng tên lửa của Iran vẫn còn nguyên vẹn và hàng nghìn UAV vẫn được cất trữ trong các hầm ngầm. Các nguồn tin cho hay nhiều kho dự trữ tên lửa dưới lòng đất ở Iran vẫn chưa bị hư hại và nước này có thể khôi phục chúng chỉ vài giờ sau khi bị không kích. Và Iran vẫn có thể phóng tên lửa vào tàu thuyền đi qua các tuyến hàng hải trong khu vực.</p><p>"Ngay cả với tốc độ phóng tên lửa và UAV như hiện nay, Iran vẫn có thể duy trì năng lực tấn công trong một thời gian nữa", Kelly Grieco, chuyên gia tại Trung tâm Stimson, nhận định.</p><p>Không chỉ về năng lực tấn công trả đũa, khả năng phòng thủ và phòng không của Iran cũng đang dần được khôi phục. Chuẩn tướng Alireza Elhami, chỉ huy Bộ tư lệnh Liên hợp Phòng không Quốc gia Iran, cho biết binh sĩ nước này đang triển khai các chiến thuật mới, kết hợp với "thiết bị hiện đại và đổi mới hệ thống phòng thủ" để đối phó chiến đấu cơ Mỹ, Israel.</p><p>Tướng Elhami không nêu cụ thể những thay đổi được lực lượng phòng không Iran áp dụng, nhưng vụ bắn rơi tiêm kích F-15E và cường kích A-10 cho thấy máy bay Mỹ và Israel không còn có thể tự do ra vào bầu trời Iran như trước, theo Courtney Kube, nhà phân tích của <i>NBC News</i>.</p><p><picture><source srcset="https://i1-vnexpress.vnecdn.net/2026/04/05/ap26085567161594-1775345940-17-6136-9031-1775345988.jpg?w=680&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=ijhfjxCEtbKgywRAgwR8ug 1x, https://i1-vnexpress.vnecdn.net/2026/04/05/ap26085567161594-1775345940-17-6136-9031-1775345988.jpg?w=1020&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=mqSBoqprmotMAmZ5F7fZGA 1.5x, https://i1-vnexpress.vnecdn.net/2026/04/05/ap26085567161594-1775345940-17-6136-9031-1775345988.jpg?w=680&amp;h=0&amp;q=100&amp;dpr=2&amp;fit=crop&amp;s=X_JF0ndDlAu_WUaqV0lSPA 2x"><img src="https://i1-vnexpress.vnecdn.net/2026/04/05/ap26085567161594-1775345940-17-6136-9031-1775345988.jpg?w=680&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=ijhfjxCEtbKgywRAgwR8ug" alt="Ông Trump tại cuộc họp nội các ở Nhà Trắng ngày 26/3. Ảnh: AP" width="680" height="453"></picture></p><p>Ông Trump tại cuộc họp nội các ở Nhà Trắng ngày 26/3. Ảnh: <i>AP</i></p><p>Điều này đẩy Mỹ vào tình thế khó khăn, đặc biệt là nếu phi công thứ hai bị lực lượng Iran bắt sống. Khi đó, bài toán ngoại giao của cuộc chiến sẽ thay đổi chỉ sau một đêm, theo giới quan sát.</p><p>"Viễn cảnh một quân nhân Mỹ có thể còn sống và đang phải lẩn trốn bên trong lãnh thổ Iran đã đẩy Washington vào thế khó trong cuộc xung đột vốn nhận được ít ủng hộ từ công chúng và chưa thấy dấu hiệu kết thúc sớm", Phil Stewart, nhà phân tích của <i>Reuters</i>, nhận xét.</p><p>Iran đã thông báo với các bên trung gian rằng họ chưa sẵn sàng gặp quan chức Mỹ tại Islamabad trong những ngày tới và những nỗ lực đạt được thỏa thuận ngừng bắn do Pakistan dẫn đầu đã đi vào ngõ cụt, theo <i>WSJ</i>.</p><p>Mỹ và Israel đã mở màn chiến dịch bằng một làn sóng tấn công khiến lãnh đạo tối cao Iran Ali Khamenei thiệt mạng. Iran đã tiến hành chiến dịch đáp trả mạnh mẽ vào Israel và các mục tiêu của Mỹ trên khắp vùng Vịnh. Tính đến 3/4, hơn 3.600 người thiệt mạng trong xung đột Iran, trong đó có 13 quân nhân Mỹ. Ít nhất 16 UAV Reaper của Mỹ đã bị bắn hạ kể từ đầu cuộc chiến, bao gồm hai chiếc trong tuần này.</p><p>Sau vụ F-15E bị bắn rơi, Chủ tịch Quốc hội Iran Mohammad-Bagher Ghalibaf đã mỉa mai ông Trump trên X rằng "sau khi đánh bại Iran 37 lần liên tiếp, cuộc chiến này giờ đã bị hạ cấp thành \'Này, có ai tìm thấy phi công của chúng tôi không?\'".</p><p>Chính quyền Tổng thống Trump đã nhiều lần tìm cách trấn an dư luận Mỹ rằng cuộc chiến Iran đang diễn ra đúng kế hoạch và sắp kết thúc. Song vụ bắn rơi tiêm kích F-15E và những hệ lụy kèm theo đã khiến tuyên bố chiến thắng của ông Trump lung lay hơn bao giờ hết, nhà phân tích Kube nhận định.</p><p><strong>Thanh Tâm</strong> (Theo <i>Reuters, CNN, NBC News</i>)</p>', '2026-04-05 07:18:02.000000', 'vu-iran-ban-ha-may-bay-doi-gao-nuoc-lanh-vao-my', 'PUBLISHED', 'Việc chiến đấu Mỹ liên tiếp bị bắn rơi phủ bóng đen lên các tuyên bố chiến thắng của ông Trump, người vừa khẳng định năng lực quân sự Iran đã "kiệt quệ".', 'https://res.cloudinary.com/du2ur4oya/image/upload/v1775373485/1775373482836_ap26085567161594-1775345940-17-6136-9031-1775345988.webp.webp', 'Vụ Iran bắn hạ máy bay \'dội gáo nước lạnh\' vào Mỹ', '2026-04-05 07:18:02.000000', 0, 1, 5, '2026-04-05 07:18:02.000000', NULL),
	(6, '<p>Do hoàn lưu vùng thấp nóng phía tây phát triển và mở rộng, nắng nóng gia tăng trên diện rộng, kéo dài nhiều ngày, nhiệt độ nhiều nơi vượt 38 độ C.</p><p>Hôm nay, khu vực Tây Bắc Bộ đã xuất hiện nắng nóng. Từ ngày 6/4, vùng thấp nóng phía tây tiếp tục phát triển và mở rộng về phía đông, khiến nắng nóng lan ra toàn bộ Bắc Bộ, bao gồm cả khu vực đồng bằng. Nhiệt độ cao nhất phổ biến 35-37 độ C, có nơi trên 38 độ và được dự báo kéo dài đến hết tuần</p><p>Theo <i>AccuWeather </i>của Mỹ, nhiệt độ tại Hà Nội trong tuần tới dao động 26-38 độ C. Các khu vực vùng núi cao trên 1500 m như Sa Pa (Lào Cai) ở mức 17-30 độ C</p><p><picture><source srcset="https://i1-vnexpress.vnecdn.net/2026/04/05/L1120744-JPG-7929-1775361718.jpg?w=680&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=-BpmgAX3ICMDcK4vPGUOyg 1x, https://i1-vnexpress.vnecdn.net/2026/04/05/L1120744-JPG-7929-1775361718.jpg?w=1020&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=Pa-6TrrUPTUGM39gvs23tA 1.5x, https://i1-vnexpress.vnecdn.net/2026/04/05/L1120744-JPG-7929-1775361718.jpg?w=680&amp;h=0&amp;q=100&amp;dpr=2&amp;fit=crop&amp;s=nPcxiiUZiK3FRoW5pBARQQ 2x"><img src="https://i1-vnexpress.vnecdn.net/2026/04/05/L1120744-JPG-7929-1775361718.jpg?w=680&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=-BpmgAX3ICMDcK4vPGUOyg" alt="Nắng nóng, người dân tham gia giao thông trên Đại Lộ Thăng Long, Hà Nội. Ảnh: Ngọc Thành" width="680" height="469"></picture></p><p>Người dân tham gia giao thông trên Đại Lộ Thăng Long, Hà Nội, khi trời nắng nóng. Ảnh: <i>Ngọc Thành</i></p><p>Trong ba ngày qua, miền Trung đã ghi nhận nắng nóng diện rộng do ảnh hưởng kết hợp của vùng thấp nóng phía tây và gió phơn. Những ngày đầu tuần, từ Thanh Hóa đến phía đông Gia Lai tiếp tục xuất hiện nắng nóng và nắng nóng gay gắt, nhiệt độ phổ biến 36-38 độ C, có nơi trên 39 độ.</p><p>Độ ẩm thấp, phổ biến 40-45 phần trăm, làm tăng nguy cơ cháy rừng và cháy nổ tại khu dân cư, nhà xưởng. Tình trạng này được dự báo duy trì đến hết tuần.</p><p>Tại Nam Bộ, nắng nóng kéo dài nhiều ngày và chưa có dấu hiệu suy giảm. Nhiệt độ cao nhất phổ biến 35-37 độ C, có nơi cao hơn. Khu vực Tây Nguyên tiếp tục duy trì trạng thái khô ráo, nắng nóng trong những ngày đầu tuần với mức nhiệt tương tự.</p><p>Theo Trung tâm Dự báo Khí tượng Thủy văn Quốc gia, trong tháng 4/2026, nắng nóng có xu hướng gia tăng trên phạm vi cả nước với cường độ gay gắt hơn trung bình nhiều năm. Nhiệt độ trung bình tại Bắc Bộ và khu vực Thanh Hóa đến Huế dự báo cao hơn 1,5-2,5 độ C so với trung bình nhiều năm; các khu vực còn lại cao hơn khoảng 0,5-1,5 độ C.</p><p><strong>Gia Chính</strong></p>', '2026-04-05 07:19:01.000000', 'tuan-toi-ca-nuoc-nang-nong', 'PUBLISHED', 'Do hoàn lưu vùng thấp nóng phía tây phát triển và mở rộng, nắng nóng gia tăng trên diện rộng, kéo dài nhiều ngày, nhiệt độ nhiều nơi vượt 38 độ C.\r\n\r\nHôm nay, khu vực Tây Bắc Bộ đã xuất hiện nắng nóng. Từ ngày 6/4, vùng thấp nóng phía tây tiếp tục phát triển và mở rộng về phía đông, khiến nắng nóng lan ra toàn bộ Bắc Bộ, bao gồm cả khu vực đồng bằng. Nhiệt độ cao nhất phổ biến 35-37 độ C, có nơi trên 38 độ và được dự báo kéo dài đến hết tuần', 'https://res.cloudinary.com/du2ur4oya/image/upload/v1775373543/1775373541237_L1120744-JPG-7929-1775361718.webp.webp', 'Tuần tới cả nước nắng nóng', '2026-04-06 16:44:13.000000', 1, 1, 4, '2026-04-05 07:19:01.000000', NULL),
	(7, '<p>Đau lưng dưới không chỉ liên quan đến căng, giãn cơ mà còn có thể cảnh báo bệnh viêm khớp, các vấn đề về đĩa đệm, bệnh thận hoặc ung thư.</p><p>Đau lưng dưới hay <a target="_blank" rel="noopener noreferrer" href="https://vnexpress.net/suc-khoe/cam-nang/dau-that-lung-239">đau thắt lưng</a> là tình trạng đau xuất hiện ở vùng từ dưới bờ xương sườn đến mông. Triệu chứng có thể từ nhẹ đến nặng, diễn ra trong thời gian ngắn (cấp tính), trung bình (bán cấp) hoặc kéo dài (mạn tính) và có thể ảnh hưởng đến bất kỳ ai. Dưới đây là một số nguyên nhân thường gặp gây đau lưng dưới.</p><p><strong>Gãy xương</strong></p><p>Gãy xương thường xảy ra do té ngã, tai nạn, chấn thương hoặc vận động lặp đi lặp lại. Một số bệnh như tiêu xương hoặc nứt đốt sống (spondylolysis) làm tăng nguy cơ gãy xương.</p><p><strong>Viêm khớp</strong></p><p>Viêm khớp, đặc biệt do thoái hóa, thường gặp ở người trên 50 tuổi. Thoái hóa khớp là một nguyên nhân điển hình gây đau lưng dưới. Viêm khớp cột sống có thể gây hẹp ống sống, làm chèn ép tủy sống cũng là nguyên nhân gây ra cơn đau.</p><p><strong>Vấn đề về đĩa đệm</strong></p><p>Đĩa đệm đóng vai trò như lớp đệm giữa các đốt sống. Khi đĩa đệm bị rách (thoát vị) hoặc phồng lên, chúng có thể chèn ép dây thần kinh và gây <a target="_blank" rel="noopener noreferrer" href="https://vnexpress.net/dau-lung-4832911.html">đau lưng</a> dưới dai dẳng.</p><p><strong>Bệnh thận</strong></p><p>Đôi khi đau lưng có thể là dấu hiệu của một vấn đề nghiêm trọng hơn, liên quan đến bệnh thận, chẳng hạn như sỏi thận. Đau lưng do bệnh thận, trái ngược với đau cơ hoặc khớp thông thường, thường nằm ở vùng đau sâu, âm ỉ, ở phần trên lưng ngay dưới khung xương sườn ở cả hai bên cột sống.</p><p>Một điểm khác biệt là loại đau lưng này thường không thay đổi theo tư thế, trong khi đau cơ xương khớp thường giảm hoặc trở nên khó chịu hơn khi thay đổi tư thế hoặc hoạt động thể chất.</p><p><strong>Ung thư</strong></p><p>Trong một số trường hợp ít gặp, đây có thể là dấu hiệu của ung thư. Các bệnh như <a target="_blank" rel="noopener noreferrer" href="https://vnexpress.net/topic/ung-thu-bang-quang-22211">ung thư bàng quang</a>, ung thư cột sống hoặc <a target="_blank" rel="noopener noreferrer" href="https://vnexpress.net/suc-khoe/cam-nang/ung-thu-phoi-298">ung thư phổi</a> đều có thể gây đau lưng. Điều đáng lo ngại là khi cơn đau kéo dài, có xu hướng tăng dần hoặc đi kèm triệu chứng bất thường khác.</p><p>Đau lưng do ung thư thường xuất hiện muộn (như ung thư bàng quang) hoặc có thể là dấu hiệu sớm (như ung thư cột sống). Khi đau không rõ nguyên nhân hoặc ngày càng nặng, người bệnh cần đi khám để được chẩn đoán kịp thời.</p><p>Đau lưng có thể xảy ra ở mọi người, kể cả trẻ em, thanh thiếu niên và trở nên phổ biến hơn khi tuổi tác tăng lên. Các yếu tố nguy cơ bao gồm ít vận động, thừa cân, bệnh lý nền, nâng vật sai cách và các vấn đề tâm lý như trầm cảm, lo âu. Hút thuốc lá cũng có thể làm tình trạng đau lưng nặng hơn.</p><p>Để giảm đau lưng dưới, bạn có thể nghỉ ngơi hợp lý, tập các <a target="_blank" rel="noopener noreferrer" href="https://vnexpress.net/5-dong-tac-yoga-giup-than-gan-khoe-manh-4941494.html">động tác yoga</a> như tư thế em bé, kết hợp chườm nóng - lạnh. Ngoài ra, vật lý trị liệu, thuốc giảm đau, massage hoặc nắn chỉnh cột sống cũng có thể giúp cải thiện triệu chứng.</p><p>Bệnh có thể phòng ngừa và kiểm soát bằng cách tập thể dục thường xuyên, duy trì cân nặng hợp lý và giữ tư thế đúng. Nếu triệu chứng trở nên nghiêm trọng hoặc kéo dài, cần can thiệp y tế kịp thời vì trì hoãn điều trị có thể khiến tình trạng xấu đi.</p><p><strong>Bảo Bảo</strong> (Theo <i>Times of India, Healthline</i>)</p>', '2026-04-05 07:20:05.000000', 'dau-lung-duoi-la-dau-hieu-benh-gi', 'PUBLISHED', 'Đau lưng dưới không chỉ liên quan đến căng, giãn cơ mà còn có thể cảnh báo bệnh viêm khớp, các vấn đề về đĩa đệm, bệnh thận hoặc ung thư.', 'https://res.cloudinary.com/du2ur4oya/image/upload/v1775373607/1775373605310_daulung-1762493044-1762493096-3373-1762493188.webp.webp', 'Đau lưng dưới là dấu hiệu bệnh gì?', '2026-04-05 07:20:05.000000', 0, 1, 6, '2026-04-05 07:20:05.000000', NULL),
	(8, '<p>AnhArsenal thủng lưới ở phút 85 và thua CLB hạng dưới Southampton 1-2 tại tứ kết Cup FA.</p><p><img src="https://is.vnecdn.net/objects/teams/41.png" alt="Southampton" width="150" height="150"></p><p><img src="https://is.vnecdn.net/objects/teams/42.png" alt="Arsenal" width="150" height="150"></p><p>Chủ nhật, ngày 5/4/2026, 02:00<a target="_blank" rel="noopener noreferrer" href="https://vnexpress.net/the-thao/du-lieu-bong-da/giai-dau/fa-cup/ket-qua">Cup FA - Tứ kết</a>Kết thúc</p><p><a target="_blank" rel="noopener noreferrer" href="https://vnexpress.net/the-thao/du-lieu-bong-da/tran-dau/1531572/southampton-arsenal"><strong>Southampton<img src="https://is.vnecdn.net/objects/teams/41.png" alt="Southampton" width="150" height="150"></strong></a></p><p><a target="_blank" rel="noopener noreferrer" href="https://vnexpress.net/the-thao/du-lieu-bong-da/tran-dau/1531572/southampton-arsenal"><strong>2 - 1Hiệp một: 1-0</strong></a></p><p><a target="_blank" rel="noopener noreferrer" href="https://vnexpress.net/the-thao/du-lieu-bong-da/tran-dau/1531572/southampton-arsenal"><strong>Arsenal<img src="https://is.vnecdn.net/objects/teams/42.png" alt="Arsenal" width="150" height="150"></strong></a></p><p><img src="https://s1.vnecdn.net/vnexpress/restruct/i/v9798/v2_2019/pc/graphics/ball.svg" alt="icon-ball" width="14" height="14">S. Charles (85\')</p><p><img src="https://s1.vnecdn.net/vnexpress/restruct/i/v9798/v2_2019/pc/graphics/ball.svg" alt="icon-ball" width="14" height="14">R. Stewart (35\')</p><p>V. Gyokeres (68\')<img src="https://s1.vnecdn.net/vnexpress/restruct/i/v9798/v2_2019/pc/graphics/ball.svg" alt="icon-ball" width="14" height="14"></p><p><a target="_blank" rel="noopener noreferrer" href="https://vnexpress.net/the-thao/du-lieu-bong-da/tran-dau/1531572/southampton-arsenal">Chi tiết trận đấu</a></p><p>Arsenal từng đứng trước cơ hội giành cú "ăn bốn" mùa này, nhưng hai thất bại liên tiếp khiến giấc mộng tan vỡ. Sau khi <a target="_blank" rel="noopener noreferrer" href="https://vnexpress.net/truc-tiep-arsenal-man-city-5053546-tong-thuat.html">thua Man City 0-2</a> ở chung kết Cup Liên đoàn, họ tiếp tục gục ngã trên sân Southampton - CLB đang thi đấu ở Championship - tại tứ kết Cup FA, đẩy mùa giải đầy hứa hẹn vào khó khăn.</p><p>Hai trận thua này không chỉ khiến hai danh hiệu vuột khỏi tay Arsenal, mà còn đặt ra dấu hỏi lớn về tâm lý và bản lĩnh của các cầu thủ trước những thời khắc then chốt.</p><p>Sức ép càng gia tăng với <a target="_blank" rel="noopener noreferrer" href="https://vnexpress.net/chu-de/mikel-arteta-1368">Mikel Arteta</a>, khi ông mới giúp Arsenal giành một danh hiệu lớn là Cup FA. Thành tích này rõ ràng không tương xứng với hơn số tiền hơn 1 tỷ USD mà CLB đã chi cho 42 tân binh trong hơn 6 năm qua, dưới thời nhà cầm quân người Tây Ban Nha.</p><p>Trước mắt Arsenal sẽ là những trận đấu có thể định đoạt cơ hội của họ ở hai đấu trường còn lại. Đoàn quân dưới trướng Arteta sẽ gặp Sporting ở hai lượt tứ kết Champions League ngày 7/4 và 15/4, xen giữa là cuộc đấu Bournemouth ở vòng 32 Ngoại hạng Anh. Kế tiếp là chuyến hành quân tới sân Etihad của Man City ngày 19/4 - trận đấu được xem là "chung kết sớm" của Ngoại hạng Anh và là thước đo thực sự cho sức mạnh và bản lĩnh của "Pháo thủ".</p><p><picture><source srcset="https://i1-thethao.vnecdn.net/2026/04/05/arsenal-PNG-1775341724-6655-1775341904.png?w=680&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=DbxaHWxwDdw7LvvbIO96Qw 1x, https://i1-thethao.vnecdn.net/2026/04/05/arsenal-PNG-1775341724-6655-1775341904.png?w=1020&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=S5dS2NDC6j8FekaAnEQqwA 1.5x, https://i1-thethao.vnecdn.net/2026/04/05/arsenal-PNG-1775341724-6655-1775341904.png?w=680&amp;h=0&amp;q=100&amp;dpr=2&amp;fit=crop&amp;s=LSxGMQP1x9OYoi29Ayjotw 2x"><img src="https://i1-thethao.vnecdn.net/2026/04/05/arsenal-PNG-1775341724-6655-1775341904.png?w=680&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=DbxaHWxwDdw7LvvbIO96Qw" alt="Các cầu thủ Arsenal thất vọng sau trận thua Southampton 1-2 ở tứ kết Cup FA trên sân St Marys, Southampton, Anh ngày 4/4/2026. Ảnh: Reuters" width="680" height="454"></picture></p><p>Các cầu thủ Arsenal thất vọng sau trận thua Southampton 1-2 ở tứ kết Cup FA trên sân St Mary\'s, Southampton, Anh ngày 4/4/2026. Ảnh: <i>Reuters</i></p><p>Trên sân St Mary\'s tối 4/4, Arteta không sử dụng đội hình mạnh nhất, do nhiều trụ cột gặp vấn đề thể trạng. Declan Rice, Bukayo Saka, Jurrien Timber hay Leandro Troussard không được đăng ký thi đấu, trong khi Willian Saliba, Martin Zubimendi ngồi ghế dự bị. Điều này khiến đội khách nhập cuộc rời rạc, để Southampton có phần làm chủ cuộc chơi. Phút 18, nếu trung vệ Cristhian Mosquera không theo đuổi quyết liệt, Leo Scienza có thể đã mở tỷ số sau khi xâm nhập vòng cấm và đẩy bóng dài vượt qua thủ thành <a target="_blank" rel="noopener noreferrer" href="https://vnexpress.net/chu-de/kepa-arrizabalaga-5411">Kepa Arrizabalaga</a> - người tiếp tục được bắt chính dù mắc lỗi trong trận chung kết Cup Liên đoàn hai tuần trước.</p><p>Từ sau phút 20, Arsenal mới giành lại thế trận, đáp trả bằng những cú sút của <a target="_blank" rel="noopener noreferrer" href="https://vnexpress.net/chu-de/martin-odegaard-3265">Martin Odegaard</a> và tài năng 16 tuổi Max Dowman, nhưng đều đi trúng vị trí mà thủ thành Daniel Peretz chọn sẵn.</p><p>Bất ngờ đến ở phút 35. Odegaard đánh gót hỏng, tạo điều kiện cho Southampton phản công. Sau đó, đến lượt <a target="_blank" rel="noopener noreferrer" href="https://vnexpress.net/chu-de/ben-white-5174">Ben White</a> phán đoán sai điểm rơi một cách căn bản, đánh đầu phá bóng hụt từ quả tạt của James Bree. Đứng ngay phía sau, Ross Stewart thoải mái khống chế rồi sút chéo góc hạ gục Kepa.</p><p>Sau<img src="https://i1-thethao.vnecdn.net/2026/04/05/arsenal1-PNG-1775342076-7296-1775342351.png?w=0&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=viW6c9eIafptx7VjBNtJng" width="680" height="431"></p><p>Bấm để lật ảnh</p><p>Trước<img src="https://i1-thethao.vnecdn.net/2026/04/05/arsenal2-PNG-1775342115-4707-1775342351.png?w=0&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=23D338aeQvQVK8dRtTr0pw" width="680" height="431"></p><p>Bấm để lật ảnh</p><p>Gyokeres ghi bàn gỡ hòa 1-1. Ảnh: <i>Reuters</i></p><p>Sang hiệp hai, Arsenal tiếp tục bế tắc, buộc Arteta phải tung Viktor Gyokeres, Nomi Madueke và Riccardo Calafiori vào sân. Tuy nhiên, Southampton mới là đội chơi lấn lướt và suýt nhân đôi cách biệt. Tom Fellows dứt điểm chệch khung thành, rồi Leo Scienza cứa lòng dội xà.</p><p>Trong thế trận khó khăn, Arsenal tìm được bàn gỡ từ tình huống phối hợp ăn ý hiếm hoi. Phút 68, Gabriel Magalhaes dâng cao, chọc khe cho Kai Havertz thoát xuống đáy biên rồi chuyền ngược lên cho Gyokeres đệm vào chân phải lưới trống.</p><p><picture><source srcset="https://i1-thethao.vnecdn.net/2026/04/05/southampton-PNG-1775342169-2485-1775342351.png?w=680&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=idlTsf6TfUQZE2W9a4A-ZQ 1x, https://i1-thethao.vnecdn.net/2026/04/05/southampton-PNG-1775342169-2485-1775342351.png?w=1020&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=XfKTWCLrjEsUm8vtHWnJCw 1.5x, https://i1-thethao.vnecdn.net/2026/04/05/southampton-PNG-1775342169-2485-1775342351.png?w=680&amp;h=0&amp;q=100&amp;dpr=2&amp;fit=crop&amp;s=J-MedzPDumZtHUliCO-pcA 2x"><img src="https://i1-thethao.vnecdn.net/2026/04/05/southampton-PNG-1775342169-2485-1775342351.png?w=680&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=idlTsf6TfUQZE2W9a4A-ZQ" alt="Các cầu thủ Southampton mừng bàn ấn định chiến thắng của Shea Charles. Ảnh: AP" width="680" height="453"></picture></p><p>Các cầu thủ Southampton mừng bàn ấn định chiến thắng của Shea Charles. Ảnh: <i>AP</i></p><p>Sau khi gỡ hòa 1-1, Arsenal không tận dụng lợi thế tâm lý để dồn ép đối phương, mà thi đấu cầm chừng. Lối chơi này khiến họ trả giá. Phút 85, Tom Fellows đi bóng từ cánh phải cắt vào trung lộ rồi kiến tạo cho cầu thủ vào sân thay người Shea Charles sút chìm về góc xa ấn định chiến thắng 2-1 và làm bùng nổ các khán đài sân St Mary\'s.</p><p>Southampton trở thành CLB hạng dưới duy nhất vào bán kết Cup FA, bên cạnh hai "ông lớn" Ngoại hạng Anh là Man City và Chelsea. Tấm vé còn lại sẽ được xác định sau trận tứ kết cuối cùng giữa Leeds và West Ham hôm nay.</p><p><strong>Hồng Duy</strong></p>', '2026-04-05 07:21:47.000000', 'arsenal-bi-loai-soc-o-cup-fa', 'PUBLISHED', 'Anh - Arsenal thủng lưới ở phút 85 và thua CLB hạng dưới Southampton 1-2 tại tứ kết Cup FA.', 'https://res.cloudinary.com/du2ur4oya/image/upload/v1775373709/1775373707179_arsenal-PNG-1775341724-6655-1775341904.webp.webp', 'Arsenal bị loại sốc ở Cup FA', '2026-04-06 16:28:18.000000', 20, 1, 1, '2026-04-05 07:21:47.000000', NULL),
	(9, '<p>Nháp News</p>', '2026-04-05 07:24:40.000000', 'nhap', 'DRAFT', 'Nháp', NULL, 'Nháp', '2026-04-05 07:24:40.000000', 0, 1, 2, NULL, NULL);

